async function boot(){try{const p=await api('/api/people');state.people=p.people;const chosen=state.people.find(x=>x.id===user())||state.people.find(x=>x.id===MAYA);localStorage.setItem('gearvault-demo-user',chosen.id);$('#person').innerHTML=state.people.map(x=>`<option value="${x.id}" ${x.id===chosen.id?'selected':''}>${x.full_name} · ${label(x.role)}</option>`).join('');await load();const q=new URLSearchParams(location.search);if(q.get('checkout')==='success'&&q.get('session_id')){await api('/api/payments/confirm',{method:'POST',body:JSON.stringify({session_id:q.get('session_id')})});history.replaceState({},'',location.pathname);flash('Payment confirmed — your dates are now held.');await load();showRecords()}else if(q.get('checkout')==='cancelled'){history.replaceState({},'',location.pathname);flash('Checkout was cancelled. No dates were held.',true)}}catch(e){flash(e.message,true)}}
