function renderNav(){const customer=state.me.role==='customer';$('#nav').innerHTML=customer?'<a href="#catalog">Catalog</a><a href="#records" data-view="records">My rentals</a><a href="#records" data-view="records">My records</a>':'<a href="#workspace">Workspace</a><a href="#catalog">Fleet</a>';$('#heroActions').innerHTML=`<a class="btn" href="#${customer?'catalog':'workspace'}">${customer?'Browse equipment':'Open my workspace'}</a>`;document.querySelectorAll('[data-view=records]').forEach(a=>a.onclick=e=>{e.preventDefault();showRecords()})}
