async function renderWorkspace(){try{const d=await api('/api/operations');const role=state.me.role;let title={rental_associate:'Counter handover & returns',bay_technician:'Serial bay',damage_assessor:'Inspection corner',shop_manager:'Manager decisions & repair bay',transfer_clerk:'Shop transfers',night_auditor:'Night books',insurance_liaison:'Hull binds',lot_runner:'Lot overview'}[role]||'Workspace';let body='';if(['rental_associate','bay_technician','damage_assessor'].includes(role)){const wanted=role==='damage_assessor'?d.reservations.filter(r=>r.status==='AWAITING_INSPECTION'):d.reservations.filter(r=>['PAID','CHECKED_OUT'].includes(r.status));body=`<div class="panel"><h3>Active papers</h3>${wanted.length?wanted.map(r=>`<div class="record"><div><h4>${r.asset_tag} · ${r.model}</h4><div class="muted">${r.customer_name} · ${r.location_name} · ${fmtDate(r.start_date)} — ${fmtDate(r.end_date)}</div>${status(r.status)}</div><div>${actionButton(r,role)}</div></div>`).join(''):'<div class="empty">Nothing is waiting in this queue.</div>'}</div>`}else if(role==='shop_manager'){body=`<div class="two-col"><div><div class="panel"><h3>Damage decisions</h3>${d.inspections.filter(i=>i.status==='PENDING').map(i=>`<div class="record"><div><h4>${i.asset_tag} · ${i.customer_name}</h4><div class="muted">${label(i.severity)} · ${i.notes||'No note'} · proposed ${money(i.proposed_cents)}</div></div><button class="btn" data-approve="${i.id}" data-proposed="${i.proposed_cents}">Decide deposit</button></div>`).join('')||'<div class="empty">No write-ups await a decision.</div>'}</div><div class="panel"><h3>Fleet wall cards & repair bay</h3>${d.units.map(u=>`<div class="record"><div><b>${u.asset_tag} · ${u.model}</b><div class="muted">${money(u.daily_rate_cents)}/day · ${status(u.status)}</div></div><button class="btn ghost" data-manage="${u.id}">Manage</button></div>`).join('')}</div></div><div class="panel"><h3>Audit log</h3>${auditTable(d.audit)}</div></div>`}else if(role==='transfer_clerk'){body=`<div class="panel"><h3>Idle floor stock</h3>${d.units.filter(u=>u.status==='AVAILABLE').map(u=>`<div class="record"><div><h4>${u.asset_tag} · ${u.model}</h4><span class="muted">Currently ${u.location_name}</span></div><div class="row"><select data-dest="${u.id}">${d.locations.filter(l=>l.id!==u.location_id).map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select><button class="btn" data-transfer="${u.id}">Request stamped move</button></div></div>`).join('')}</div>`}else if(role==='night_auditor'){body=`<div class="panel"><h3>Immutable activity book</h3>${auditTable(d.audit)}</div>`}else if(role==='insurance_liaison'){body=`<div class="panel"><h3>Signed hull binds</h3>${d.binds?.length?`<pre>${JSON.stringify(d.binds,null,2)}</pre>`:'<div class="empty">No hull binds have been recorded.</div>'}</div>`}else{body=`<div class="panel"><h3>Fleet overview</h3><p class="muted">Lot runners can see where gear rests, but cannot drive transfers or work the counter.</p><div class="grid">${d.units.map(card).join('')}</div></div>`}$('#content').innerHTML=`<div class="section" id="workspace"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">${label(role)}</p><h2>${title}</h2></div></div><div class="role-banner">Signed in as <b>${state.me.full_name}</b>. This workspace only offers work assigned to your role.</div>${body}</div>`;bindOps(d)}catch(e){flash(e.message,true)}}
function auditTable(log=[]){return `<table class="table"><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Record</th></tr></thead><tbody>${log.map(a=>`<tr><td>${new Date(a.created_at).toLocaleString()}</td><td>${a.actor_name}</td><td>${label(a.action)}</td><td>${a.entity_type} · ${a.entity_id.slice(0,8)}</td></tr>`).join('')}</tbody></table>`}
function bindOps(d){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.dataset.action==='inspect')return inspectDialog(b.dataset.id);try{const x=await api(`/api/reservations/${b.dataset.id}/${b.dataset.action}`,{method:'POST',body:'{}'});flash(x.message);await load()}catch(e){flash(e.message,true)}});document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveDialog(b.dataset.approve,b.dataset.proposed));document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>manageDialog(d.units.find(u=>u.id===b.dataset.manage)));document.querySelectorAll('[data-transfer]').forEach(b=>b.onclick=async()=>{try{const to=document.querySelector(`[data-dest="${b.dataset.transfer}"]`).value,x=await api(`/api/units/${b.dataset.transfer}/transfer`,{method:'POST',body:JSON.stringify({to_location_id:to})});flash(x.message);await load()}catch(e){flash(e.message,true)}})}
